234	    @Override
235	    @Transactional
236	    public void saveOwner(Owner owner) throws DataAccessException {
237	        if (owner.isNew() && isDuplicateEmail(owner)) {
238	            throw new DuplicateOwnerException(
239	                "An owner with the same email already exists");
240	        }
241	        if (owner.isNew() && isDuplicateTelephone(owner)) {
242	            throw new DuplicateOwnerException(
243	                "An owner with the same telephone already exists");
244	        }
245	        if (owner.isNew() && isDuplicateOwner(owner)) {
246	            throw new DuplicateOwnerException(
247	                "An owner with the same last name and telephone already exists");
248	        }
249	        if (owner.getRegistrationDate() == null) {
250	            owner.setRegistrationDate(LocalDate.now());
251	        }
252	        ownerRepository.save(owner);
253	
254	    }
255	
256	    private boolean isDuplicateEmail(Owner owner) {
257	        if (owner.getEmail() == null) {
258	            return false;
259	        }
260	        String email = normalizeKey(owner.getEmail());
261	        return ownerRepository.findAll().stream()
262	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
263	                && Objects.equals(normalizeKey(existing.getEmail()), email));
264	    }
265	
266	    private boolean isDuplicateTelephone(Owner owner) {
267	        if (owner.getTelephone() == null) {
268	            return false;
269	        }
270	        String telephone = normalizeKey(owner.getTelephone());
271	        return ownerRepository.findAll().stream()
272	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
273	                && Objects.equals(normalizeKey(existing.getTelephone()), telephone));
274	    }
275	
276	    private boolean isDuplicateOwner(Owner owner) {
277	        if (owner.getLastName() == null) {
278	            return false;
279	        }
280	        String lastName = normalizeKey(owner.getLastName());
281	        String telephone = normalizeKey(owner.getTelephone());
282	        return ownerRepository.findAll().stream()
283	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
284	                && Objects.equals(normalizeKey(existing.getLastName()), lastName)
285	                && Objects.equals(normalizeKey(existing.getTelephone()), telephone));
286	    }
287	
288	    /**
289	     * Normalizes a value for duplicate detection so that comparisons ignore
290	     * letter case and surrounding or repeated whitespace (e.g. {@code
291	     * "  john   smith "} and {@code "John Smith"} are treated as equal).
292	     */
293	    private static String normalizeKey(String value) {
294	        if (value == null) {
295	            return null;
296	        }
297	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
298	    }
